      if (settled) return;
      settled = true;
      clearTimeout(timer);
      signal?.removeEventListener('abort', cancel);
      media.removeEventListener('loadedmetadata', ready);
      media.removeEventListener('durationchange', ready);
      media.removeEventListener('error', failed);
